  subroutine check_ch4_type(this, label, nmiss)
    type(ch4_type), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    if (associated(this%ch4_prod_depth_sat_col)) call dd_miss(acc_is_present(this%ch4_prod_depth_sat_col), label, &
         'ch4_prod_depth_sat_col', nmiss)
    if (associated(this%ch4_prod_depth_unsat_col)) call dd_miss(acc_is_present(this%ch4_prod_depth_unsat_col), label, &
         'ch4_prod_depth_unsat_col', nmiss)
    if (allowlakeprod .and. use_lch4) then
       if (associated(this%ch4_prod_depth_lake_col)) call dd_miss(acc_is_present(this%ch4_prod_depth_lake_col), label, &
            'ch4_prod_depth_lake_col', nmiss)
    end if
    if (associated(this%ch4_oxid_depth_sat_col)) call dd_miss(acc_is_present(this%ch4_oxid_depth_sat_col), label, &
         'ch4_oxid_depth_sat_col', nmiss)
    if (associated(this%ch4_oxid_depth_unsat_col)) call dd_miss(acc_is_present(this%ch4_oxid_depth_unsat_col), label, &
         'ch4_oxid_depth_unsat_col', nmiss)
    if (allowlakeprod .and. use_lch4) then
       if (associated(this%ch4_oxid_depth_lake_col)) call dd_miss(acc_is_present(this%ch4_oxid_depth_lake_col), label, &
            'ch4_oxid_depth_lake_col', nmiss)
    end if
    if (associated(this%ch4_aere_depth_sat_col)) call dd_miss(acc_is_present(this%ch4_aere_depth_sat_col), label, &
         'ch4_aere_depth_sat_col', nmiss)
    if (associated(this%ch4_aere_depth_unsat_col)) call dd_miss(acc_is_present(this%ch4_aere_depth_unsat_col), label, &
         'ch4_aere_depth_unsat_col', nmiss)
    if (associated(this%ch4_tran_depth_sat_col)) call dd_miss(acc_is_present(this%ch4_tran_depth_sat_col), label, &
