  subroutine check_column_carbon_state(this, label, nmiss)
    type(column_carbon_state), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_column_nutrient_state(this%core, trim(label)//'%core', nmiss)
    if (.not. use_fates .and. use_cn) then
       if (associated(this%rootc)) call dd_miss(acc_is_present(this%rootc), label, 'rootc', nmiss)
    end if
    if (.not. use_fates .and. use_cn) then
       if (associated(this%leafc)) call dd_miss(acc_is_present(this%leafc), label, 'leafc', nmiss)
    end if
    if (.not. use_fates .and. use_cn) then
       if (associated(this%deadstemc)) call dd_miss(acc_is_present(this%deadstemc), label, 'deadstemc', nmiss)
    end if
    if (associated(this%fuelc)) call dd_miss(acc_is_present(this%fuelc), label, 'fuelc', nmiss)
    if (.not. use_fates .and. use_cn) then
       if (associated(this%fuelc_crop)) call dd_miss(acc_is_present(this%fuelc_crop), label, 'fuelc_crop', nmiss)
    end if
    if (associated(this%frootc)) call dd_miss(acc_is_present(this%frootc), label, 'frootc', nmiss)
    if (use_cn .or. use_fates) then
       if (associated(this%totabgc)) call dd_miss(acc_is_present(this%totabgc), label, 'totabgc', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%totvegc_abg)) call dd_miss(acc_is_present(this%totvegc_abg), label, 'totvegc_abg', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%decomp_som2c_vr)) call dd_miss(acc_is_present(this%decomp_som2c_vr), label, &
            'decomp_som2c_vr', nmiss)
    end if
    if (associated(this%core%totveg)) call dd_miss(acc_is_present(this%core%totveg), label, 'core%totveg', nmiss)
    if (use_cn .or. use_fates) then
       if (associated(this%core%decomp_pools_vr)) call dd_miss(acc_is_present(this%core%decomp_pools_vr), label, &
            'core%decomp_pools_vr', nmiss)
    end if
    if (associated(this%core%trunc_sink_vr)) call dd_miss(acc_is_present(this%core%trunc_sink_vr), label, &
         'core%trunc_sink_vr', nmiss)
    if (associated(this%core%seed)) call dd_miss(acc_is_present(this%core%seed), label, 'core%seed', nmiss)
    if (associated(this%core%prod1)) call dd_miss(acc_is_present(this%core%prod1), label, 'core%prod1', nmiss)
    if (associated(this%core%prod10)) call dd_miss(acc_is_present(this%core%prod10), label, 'core%prod10', nmiss)
    if (associated(this%core%prod100)) call dd_miss(acc_is_present(this%core%prod100), label, 'core%prod100', nmiss)
    if (associated(this%core%totprod)) call dd_miss(acc_is_present(this%core%totprod), label, 'core%totprod', nmiss)
    if (associated(this%core%dyn_bal_adjustments)) call dd_miss(acc_is_present(this%core%dyn_bal_adjustments), label, &
         'core%dyn_bal_adjustments', nmiss)
    if (associated(this%core%totpft)) call dd_miss(acc_is_present(this%core%totpft), label, 'core%totpft', nmiss)
    if (associated(this%core%decomp_pools_1m)) call dd_miss(acc_is_present(this%core%decomp_pools_1m), label, &
         'core%decomp_pools_1m', nmiss)
    if (associated(this%core%decomp_pools)) call dd_miss(acc_is_present(this%core%decomp_pools), label, &
         'core%decomp_pools', nmiss)
