    if (associated(this%core%totsom)) call dd_miss(acc_is_present(this%core%totsom), label, 'core%totsom', nmiss)
    if (associated(this%core%som1)) call dd_miss(acc_is_present(this%core%som1), label, 'core%som1', nmiss)
