  subroutine check_column_nitrogen_state(this, label, nmiss)
    type(column_nitrogen_state), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_column_mineral_state(this%mineral, trim(label)//'%mineral', nmiss)
    call check_column_nutrient_state(this%core, trim(label)//'%core', nmiss)
    if (associated(this%smin_no3_vr)) call dd_miss(acc_is_present(this%smin_no3_vr), label, 'smin_no3_vr', nmiss)
    if (associated(this%smin_nh4_vr)) call dd_miss(acc_is_present(this%smin_nh4_vr), label, 'smin_nh4_vr', nmiss)
    if (associated(this%smin_nh4sorb_vr)) call dd_miss(acc_is_present(this%smin_nh4sorb_vr), label, &
         'smin_nh4sorb_vr', nmiss)
    if (associated(this%smin_no3)) call dd_miss(acc_is_present(this%smin_no3), label, 'smin_no3', nmiss)
    if (associated(this%smin_nh4)) call dd_miss(acc_is_present(this%smin_nh4), label, 'smin_nh4', nmiss)
    if (associated(this%smin_nh4sorb)) call dd_miss(acc_is_present(this%smin_nh4sorb), label, 'smin_nh4sorb', nmiss)
    if (use_cn .or. use_fates) then
       if (associated(this%totabgn)) call dd_miss(acc_is_present(this%totabgn), label, 'totabgn', nmiss)
    end if
    if (use_cn .or. use_fates) then
