  subroutine update_column_nutrient_state(this, to_device)
    type(column_nutrient_state), intent(inout), target :: this
    logical, intent(in) :: to_device
    integer :: i_
#ifdef _OPENACC
    !$acc update device(this%species) if(to_device)
    !$acc update self(this%species) if(.not. to_device)
    if (associated(this%totveg)) then
       !$acc update device(this%totveg) if(to_device)
       !$acc update self(this%totveg) if(.not. to_device)
    end if
    if (associated(this%decomp_pools_vr)) then
       !$acc update device(this%decomp_pools_vr) if(to_device)
       !$acc update self(this%decomp_pools_vr) if(.not. to_device)
