  subroutine check_column_phosphorus_flux(this, label, nmiss)
    type(column_phosphorus_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_column_mineral_flux(this%mineral, trim(label)//'%mineral', nmiss)
    call check_column_uptake_flux(this%uptake, trim(label)//'%uptake', nmiss)
    call check_column_nutrient_flux(this%core, trim(label)//'%core', nmiss)
    if (associated(this%fert_p_to_sminp)) call dd_miss(acc_is_present(this%fert_p_to_sminp), label, &
         'fert_p_to_sminp', nmiss)
    if (associated(this%potential_immob_p_vr)) call dd_miss(acc_is_present(this%potential_immob_p_vr), label, &
         'potential_immob_p_vr', nmiss)
    if (associated(this%potential_immob_p)) call dd_miss(acc_is_present(this%potential_immob_p), label, &
         'potential_immob_p', nmiss)
    if (associated(this%actual_immob_p_vr)) call dd_miss(acc_is_present(this%actual_immob_p_vr), label, &
         'actual_immob_p_vr', nmiss)
    if (associated(this%actual_immob_p)) call dd_miss(acc_is_present(this%actual_immob_p), label, 'actual_immob_p', &
         nmiss)
