  subroutine attach_conctransporttype(this)
    type(conctransporttype), intent(inout), target :: this
    integer :: i_
#ifdef _OPENACC
    if (use_cn .or. use_fates) then
       if (associated(this%conc_ptr)) then
          !$acc enter data attach(this%conc_ptr)
       end if
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%src_ptr)) then
          !$acc enter data attach(this%src_ptr)
       end if
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%trcr_tend_ptr)) then
