  subroutine check_conctransporttype(this, label, nmiss)
    type(conctransporttype), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    if (use_cn .or. use_fates) then
       if (associated(this%conc_ptr)) call dd_miss(acc_is_present(this%conc_ptr), label, 'conc_ptr', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%src_ptr)) call dd_miss(acc_is_present(this%src_ptr), label, 'src_ptr', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%trcr_tend_ptr)) call dd_miss(acc_is_present(this%trcr_tend_ptr), label, 'trcr_tend_ptr', nmiss)
    end if
#endif
  end subroutine check_conctransporttype

