  subroutine check_elm_interface_bgc_datatype(this, label, nmiss)
    type(elm_interface_bgc_datatype), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    if (associated(this%floating_cn_ratio)) call dd_miss(acc_is_present(this%floating_cn_ratio), label, &
         'floating_cn_ratio', nmiss)
    if (associated(this%floating_cp_ratio)) call dd_miss(acc_is_present(this%floating_cp_ratio), label, &
         'floating_cp_ratio', nmiss)
    if (associated(this%initial_cn_ratio)) call dd_miss(acc_is_present(this%initial_cn_ratio), label, &
         'initial_cn_ratio', nmiss)
    if (associated(this%initial_cp_ratio)) call dd_miss(acc_is_present(this%initial_cp_ratio), label, &
         'initial_cp_ratio', nmiss)
    if (associated(this%finundated_col)) call dd_miss(acc_is_present(this%finundated_col), label, 'finundated_col', &
         nmiss)
