  subroutine check_gridcell_carbon_flux(this, label, nmiss)
    type(gridcell_carbon_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_gridcell_nutrient_flux(this%core, trim(label)//'%core', nmiss)
    if (associated(this%dwt_conv_cflux_dribbled)) call dd_miss(acc_is_present(this%dwt_conv_cflux_dribbled), label, &
         'dwt_conv_cflux_dribbled', nmiss)
    if (associated(this%hrv_deadstemc_to_prod10c)) call dd_miss(acc_is_present(this%hrv_deadstemc_to_prod10c), label, &
         'hrv_deadstemc_to_prod10c', nmiss)
    if (associated(this%hrv_deadstemc_to_prod100c)) call dd_miss(acc_is_present(this%hrv_deadstemc_to_prod100c), &
         label, 'hrv_deadstemc_to_prod100c', nmiss)
    if (use_cn .or. use_fates) then
       if (associated(this%gpp)) call dd_miss(acc_is_present(this%gpp), label, 'gpp', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%er)) call dd_miss(acc_is_present(this%er), label, 'er', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%fire_closs)) call dd_miss(acc_is_present(this%fire_closs), label, 'fire_closs', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%prod1_loss)) call dd_miss(acc_is_present(this%prod1_loss), label, 'prod1_loss', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%prod10_loss)) call dd_miss(acc_is_present(this%prod10_loss), label, 'prod10_loss', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%prod100_loss)) call dd_miss(acc_is_present(this%prod100_loss), label, 'prod100_loss', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%hrv_xsmrpool_to_atm)) call dd_miss(acc_is_present(this%hrv_xsmrpool_to_atm), label, &
            'hrv_xsmrpool_to_atm', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%som_c_leached)) call dd_miss(acc_is_present(this%som_c_leached), label, 'som_c_leached', nmiss)
    end if
    if (use_cn .or. use_fates) then
       if (associated(this%somc_yield)) call dd_miss(acc_is_present(this%somc_yield), label, 'somc_yield', nmiss)
    end if
    if (associated(this%core%dwt_seed_to_leaf)) call dd_miss(acc_is_present(this%core%dwt_seed_to_leaf), label, &
         'core%dwt_seed_to_leaf', nmiss)
    if (associated(this%core%dwt_seed_to_deadstem)) call dd_miss(acc_is_present(this%core%dwt_seed_to_deadstem), &
         label, 'core%dwt_seed_to_deadstem', nmiss)
    if (associated(this%core%dwt_conv_flux)) call dd_miss(acc_is_present(this%core%dwt_conv_flux), label, &
         'core%dwt_conv_flux', nmiss)
    if (associated(this%core%dwt_prod10_gain)) call dd_miss(acc_is_present(this%core%dwt_prod10_gain), label, &
         'core%dwt_prod10_gain', nmiss)
    if (associated(this%core%dwt_prod100_gain)) call dd_miss(acc_is_present(this%core%dwt_prod100_gain), label, &
         'core%dwt_prod100_gain', nmiss)
    if (associated(this%core%inputs)) call dd_miss(acc_is_present(this%core%inputs), label, 'core%inputs', nmiss)
    if (associated(this%core%outputs)) call dd_miss(acc_is_present(this%core%outputs), label, 'core%outputs', nmiss)
#endif
