       !$acc update device(this%core%outputs) if(to_device)
       !$acc update self(this%core%outputs) if(.not. to_device)
    end if
#endif
  end subroutine update_gridcell_phosphorus_flux

  subroutine check_gridcell_phosphorus_flux(this, label, nmiss)
    type(gridcell_phosphorus_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_gridcell_nutrient_flux(this%core, trim(label)//'%core', nmiss)
    if (associated(this%dwt_seedp_to_ppool)) call dd_miss(acc_is_present(this%dwt_seedp_to_ppool), label, &
         'dwt_seedp_to_ppool', nmiss)
    if (associated(this%core%dwt_seed_to_leaf)) call dd_miss(acc_is_present(this%core%dwt_seed_to_leaf), label, &
         'core%dwt_seed_to_leaf', nmiss)
    if (associated(this%core%dwt_seed_to_deadstem)) call dd_miss(acc_is_present(this%core%dwt_seed_to_deadstem), &
         label, 'core%dwt_seed_to_deadstem', nmiss)
    if (associated(this%core%dwt_conv_flux)) call dd_miss(acc_is_present(this%core%dwt_conv_flux), label, &
         'core%dwt_conv_flux', nmiss)
    if (associated(this%core%dwt_prod10_gain)) call dd_miss(acc_is_present(this%core%dwt_prod10_gain), label, &
         'core%dwt_prod10_gain', nmiss)
    if (associated(this%core%dwt_prod100_gain)) call dd_miss(acc_is_present(this%core%dwt_prod100_gain), label, &
         'core%dwt_prod100_gain', nmiss)
    if (associated(this%core%inputs)) call dd_miss(acc_is_present(this%core%inputs), label, 'core%inputs', nmiss)
    if (associated(this%core%outputs)) call dd_miss(acc_is_present(this%core%outputs), label, 'core%outputs', nmiss)
#endif
  end subroutine check_gridcell_phosphorus_flux

  ! ---- gridcell_phosphorus_state (gridcelldatatype)

  subroutine deepcopy_gridcell_phosphorus_state(this)
    type(gridcell_phosphorus_state), intent(inout), target :: this
    integer :: i_
#ifdef _OPENACC
    if (use_cn .or. use_fates) then
       call deepcopy_gridcell_nutrient_state(this%core)
    end if
    !$acc update device(this%core%species)
    if (associated(this%core%seed)) then
       !$acc enter data copyin(this%core%seed)
    end if
    if (associated(this%core%balance_beg)) then
       !$acc enter data copyin(this%core%balance_beg)
    end if
    if (associated(this%core%balance_end)) then
       !$acc enter data copyin(this%core%balance_end)
    end if
    if (associated(this%core%balance_err)) then
       !$acc enter data copyin(this%core%balance_err)
    end if
#endif
  end subroutine deepcopy_gridcell_phosphorus_state

  subroutine update_gridcell_phosphorus_state(this, to_device)
    type(gridcell_phosphorus_state), intent(inout), target :: this
    logical, intent(in) :: to_device
    integer :: i_
#ifdef _OPENACC
    if (use_cn .or. use_fates) then
       call update_gridcell_nutrient_state(this%core, to_device)
    end if
    !$acc update device(this%core%species) if(to_device)
    !$acc update self(this%core%species) if(.not. to_device)
    if (associated(this%core%seed)) then
       !$acc update device(this%core%seed) if(to_device)
       !$acc update self(this%core%seed) if(.not. to_device)
    end if
    if (associated(this%core%balance_beg)) then
       !$acc update device(this%core%balance_beg) if(to_device)
       !$acc update self(this%core%balance_beg) if(.not. to_device)
    end if
    if (associated(this%core%balance_end)) then
       !$acc update device(this%core%balance_end) if(to_device)
       !$acc update self(this%core%balance_end) if(.not. to_device)
    end if
    if (associated(this%core%balance_err)) then
       !$acc update device(this%core%balance_err) if(to_device)
       !$acc update self(this%core%balance_err) if(.not. to_device)
    end if
#endif
  end subroutine update_gridcell_phosphorus_state

  subroutine check_gridcell_phosphorus_state(this, label, nmiss)
    type(gridcell_phosphorus_state), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    if (use_cn .or. use_fates) then
       call check_gridcell_nutrient_state(this%core, trim(label)//'%core', nmiss)
    end if
    if (associated(this%core%seed)) call dd_miss(acc_is_present(this%core%seed), label, 'core%seed', nmiss)
    if (associated(this%core%balance_beg)) call dd_miss(acc_is_present(this%core%balance_beg), label, &
         'core%balance_beg', nmiss)
    if (associated(this%core%balance_end)) call dd_miss(acc_is_present(this%core%balance_end), label, &
         'core%balance_end', nmiss)
    if (associated(this%core%balance_err)) call dd_miss(acc_is_present(this%core%balance_err), label, &
         'core%balance_err', nmiss)
#endif
  end subroutine check_gridcell_phosphorus_state

  subroutine dd_miss(present_, label, comp, nmiss)
    ! count (and report the first 50 of) the arrays not present on the device
    logical, intent(in) :: present_
    character(len=*), intent(in) :: label, comp
    integer, intent(inout) :: nmiss
    if (present_) return
    nmiss = nmiss + 1
    if (nmiss <= 50) write(iulog,*) 'elm_device: not present: ', trim(label)//'%'//comp
  end subroutine dd_miss

end module DeepCopySoilNutrientMod
